// Example of conditional rendering based on state and data
function ExampleComponent({ items }: { items: string[] }) {
  const [showItems, setShowItems] = useState<boolean>(false);

  return (
    <div>
      <button onClick={() => setShowItems(!showItems)}>Toggle</button>
      {showItems && items.length > 0 && (
        <ul>
          {items.map((item) => (
            <li key={item}>{item}</li>
          ))}
        </ul>
      )}
    </div>
  );
}

